import { useQuery } from '@tanstack/react-query';
import { fetchPosts } from '../api/posts';

function PostsList() {
  const {
    data: posts,
    isError,
    error,
    refetch
  } = useQuery({
    queryKey: ['posts'],
    queryFn: fetchPosts
  });

  if (isError) {
    return (
      <div role="alert" className="error-banner">
        <h3>Unable to load posts</h3>
        <p>{error?.message ?? 'Something went wrong. Please try again.'}</p>
        <button onClick={() => refetch()}>Retry now</button>
      </div>
    );
  }

  return (
    <ul>
      {posts?.map((post) => (
        <li key={post.id}>{post.title}</li>
      ))}
    </ul>
  );
}

import { QueryClient } from '@tanstack/react-query';

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: (failureCount, error) => {
        if (error.status === 404) return false;
        return failureCount < 3;
      },
      retryDelay: (attemptIndex) =>
        Math.min(1000 * 2 ** attemptIndex, 30000),
    },
    mutations: {
      retry: false,
    },
  },
  // Global error logger
  onError: (error, query, context) => {
    console.error('[React Query Error]', {
      queryKey: query?.queryKey,
      message: error.message,
      status: (error as any)?.status,
      variables: query?.meta,
    });
    // Replace with: Sentry.captureException(error);
  },
  onSettled: (data, error, query) => {
    if (query) {
      queryClient.invalidateQueries({ queryKey: query.queryKey });
    }
  },
});

import { Component, type ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

class QueryErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false, error: null };

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, info: { componentStack: string }) {
    console.error('Unhandled query render error:', error, info);
  }

  render() {
    if (this.state.hasError) {
    return (
      <div role="alert" className="error-fallback">
        <h2>Something went wrong</h2>
        <p>{this.state.error?.message}</p>
        {this.props.fallback}
      </div>
    );
  }

  return this.props.children;
}

// Usage
function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <QueryErrorBoundary
        fallback={<button onClick={() => location.reload()}>Reload page</button>}
      >
        <PostsPage />
      </QueryErrorBoundary>
    </QueryClientProvider>
  );
}

type HttpStatus = number;

const FRIENDLY_MESSAGES: Record<HttpStatus, string> = {
  400: 'The request was invalid. Please check your input and try again.',
  401: 'Your session has expired. Please sign in again.',
  403: 'You don't have permission to do that.',
  404: 'The resource you are looking for doesn't exist.',
  409: 'This conflicts with existing data. Please refresh and try again.',
  422: 'The data sent was not valid. Please correct the highlighted fields.',
  429: 'Too many requests. Please wait a moment and try again.',
  500: 'Something went wrong on our end. Please try again later.',
  502: 'The server is temporarily unavailable. Please try again soon.',
  503: 'The service is undergoing maintenance. Please try again shortly.',
};

export function getFriendlyErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    const status = (error as any)?.status as HttpStatus | undefined;
    if (status && FRIENDLY_MESSAGES[status]) {
      return FRIENDLY_MESSAGES[status];
    }
    return error.message || 'Something went wrong. Please try again.';
  }
  return 'An unexpected error occurred. Please try again later.';
}
